//! Factory tables, generated by code (no file is copied or shipped).
//! Every frame is normalized to a peak of 1.

use std::f32::consts::{PI, TAU};

use musiccraft_dsp::fft::Fft;

use crate::ops::normalize;
use crate::spectrum::{self, HARMONICS, Partial};
use crate::{FRAME_LEN, Table};

/// Frames in each factory table.
const FRAMES: usize = 64;

/// The factory tables, in menu order.
#[must_use]
pub fn names() -> &'static [&'static str] {
    &[
        "basic",
        "analog",
        "pwm",
        "additive",
        "odd_even",
        "formant",
        "fm",
        "fm_ratio",
        "sync",
        "noise",
        "harmonic_morph",
    ]
}

/// Builds factory table `name`; `None` for an unknown name.
#[must_use]
pub fn table(name: &str) -> Option<Table> {
    let mut table = match name {
        "basic" => sampled(basic),
        "analog" => additive(analog),
        "pwm" => additive(pwm),
        "additive" => additive(|y, h| {
            let count = (y * (FRAMES - 1) as f32).round() as usize + 1;
            if h <= count { saw(h) } else { (0.0, 0.0) }
        }),
        "odd_even" => additive(|y, h| {
            let (s, c) = saw(h);
            let weight = if h % 2 == 1 { 1.0 - y } else { y };
            (s.abs() * weight, c)
        }),
        "formant" => additive(formant),
        "fm" => sampled(|y, x| (TAU * x + 8.0 * y * (TAU * x).sin()).sin()),
        "fm_ratio" => sampled(|y, x| {
            // Crossfade between whole ratios so every frame stays one cycle.
            let r = 1.0 + 7.0 * y;
            let (lo, t) = (r.floor(), r - r.floor());
            let fm = |ratio: f32| (TAU * x + 2.0 * (TAU * ratio * x).sin()).sin();
            fm(lo) * (1.0 - t) + fm(lo + 1.0) * t
        }),
        "sync" => sampled(|y, x| 2.0 * (x * (1.0 + 7.0 * y)).rem_euclid(1.0) - 1.0),
        "noise" => noise(),
        "harmonic_morph" => harmonic_morph(),
        _ => return None,
    };
    let frames = table.frames();
    for frame in 0..frames {
        let mut samples = table.frame(frame).map(<[f32]>::to_vec).unwrap_or_default();
        normalize(&mut samples);
        table.set_frame(frame, &samples);
    }
    Some(table)
}

/// The synth's default: sine → triangle → saw → square.
fn basic(y: f32, x: f32) -> f32 {
    let sine = (x * TAU).sin();
    let triangle = 1.0 - 4.0 * ((x + 0.25).rem_euclid(1.0) - 0.5).abs();
    let saw = 2.0 * (x + 0.5).rem_euclid(1.0) - 1.0;
    let square = if x < 0.5 { 1.0 } else { -1.0 };
    let shapes = [sine, triangle, saw, square];
    let pos = y * 3.0;
    let i = (pos.floor() as usize).min(2);
    let t = pos - i as f32;
    let a = shapes.get(i).copied().unwrap_or(0.0);
    let b = shapes.get(i + 1).copied().unwrap_or(0.0);
    a * (1.0 - t) + b * t
}

/// Oversampling for [`sampled`]: harmonics up to this many times the
/// frame's limit are computed, then dropped, so sharp edges don't fold back.
const OVERSAMPLE: usize = 8;

/// A table of a waveform function of (y, x), band-limited to the frame.
fn sampled(f: impl Fn(f32, f32) -> f32) -> Table {
    let len = FRAME_LEN * OVERSAMPLE;
    let fft = Fft::new(len);
    let mut data = Vec::with_capacity(FRAMES * FRAME_LEN);
    for frame in 0..FRAMES {
        let y = frame as f32 / (FRAMES - 1) as f32;
        let mut buf: Vec<(f32, f32)> = (0..len)
            .map(|i| (f(y, i as f32 / len as f32), 0.0))
            .collect();
        fft.forward(&mut buf);
        let mut bins = vec![(0.0, 0.0); FRAME_LEN];
        for h in 1..=HARMONICS {
            let (re, im) = buf.get(h).copied().unwrap_or_default();
            if let Some(bin) = bins.get_mut(h) {
                *bin = (re / OVERSAMPLE as f32, im / OVERSAMPLE as f32);
            }
        }
        data.extend(spectrum::inverse(bins));
    }
    Table::new(&data).unwrap_or_default()
}

/// A table from each harmonic's (sine, cosine) amplitude as a function of
/// (y, harmonic).
fn additive(f: impl Fn(f32, usize) -> (f32, f32)) -> Table {
    let mut data = Vec::with_capacity(FRAMES * FRAME_LEN);
    for frame in 0..FRAMES {
        let y = frame as f32 / (FRAMES - 1) as f32;
        let partials: Vec<Partial> = (1..=HARMONICS)
            .map(|h| {
                let (s, c) = f(y, h);
                Partial {
                    magnitude: (s * s + c * c).sqrt(),
                    phase: (c.atan2(s) / TAU).rem_euclid(1.0),
                }
            })
            .collect();
        data.extend(spectrum::from_partials(&partials));
    }
    Table::new(&data).unwrap_or_default()
}

/// A saw's harmonic `h`, as (sine, cosine) amplitudes.
fn saw(h: usize) -> (f32, f32) {
    (2.0 / (PI * h as f32), 0.0)
}

/// Gentle analogue roll-off: rounded edges.
fn rolloff(h: usize) -> f32 {
    1.0 / (1.0 + (h as f32 / 24.0).powi(2))
}

/// Saw → square → triangle, rounded.
fn analog(y: f32, h: usize) -> (f32, f32) {
    let hf = h as f32;
    let odd = h % 2 == 1;
    let square = if odd { 4.0 / (PI * hf) } else { 0.0 };
    let triangle = if odd {
        let sign = if (h / 2) % 2 == 0 { 1.0 } else { -1.0 };
        sign * 8.0 / (PI * PI * hf * hf)
    } else {
        0.0
    };
    let shapes = [saw(h).0, square, triangle];
    let pos = y * 2.0;
    let i = (pos.floor() as usize).min(1);
    let t = pos - i as f32;
    let a = shapes.get(i).copied().unwrap_or(0.0);
    let b = shapes.get(i + 1).copied().unwrap_or(0.0);
    ((a * (1.0 - t) + b * t) * rolloff(h), 0.0)
}

/// A pulse narrowing from 50 % to 2 % width.
fn pwm(y: f32, h: usize) -> (f32, f32) {
    let width = 0.5 - 0.48 * y;
    let hf = h as f32;
    let angle = TAU * hf * width;
    let scale = 2.0 / (PI * hf);
    (scale * (1.0 - angle.cos()), scale * angle.sin())
}

/// Vowel formants (F1, F2 in Hz): textbook averages for adult speakers.
const VOWELS: [(f32, f32); 5] = [
    (730.0, 1090.0), // a
    (530.0, 1840.0), // e
    (270.0, 2290.0), // i
    (570.0, 840.0),  // o
    (300.0, 870.0),  // u
];

/// A 110 Hz saw through two formant resonances, a → e → i → o → u.
fn formant(y: f32, h: usize) -> (f32, f32) {
    let pos = y * (VOWELS.len() - 1) as f32;
    let i = (pos.floor() as usize).min(VOWELS.len() - 2);
    let t = pos - i as f32;
    let (a1, a2) = VOWELS.get(i).copied().unwrap_or_default();
    let (b1, b2) = VOWELS.get(i + 1).copied().unwrap_or_default();
    let (f1, f2) = (a1 + (b1 - a1) * t, a2 + (b2 - a2) * t);
    let freq = 110.0 * h as f32;
    let peak = |center: f32| {
        let width = 60.0 + 0.08 * center;
        1.0 / (1.0 + ((freq - center) / width).powi(2))
    };
    let gain = 0.05 + peak(f1) + 0.6 * peak(f2);
    (saw(h).0 * gain, 0.0)
}

/// A small fixed-seed generator (xorshift), so tables never change.
struct Random(u32);

impl Random {
    fn next(&mut self) -> f32 {
        self.0 ^= self.0 << 13;
        self.0 ^= self.0 >> 17;
        self.0 ^= self.0 << 5;
        self.0 as f32 / u32::MAX as f32
    }
}

/// 16 random 1/f spectra, crossfaded across the frames.
fn noise() -> Table {
    const KEYS: usize = 16;
    let mut random = Random(0x5EED_0001);
    let keys: Vec<Vec<(f32, f32)>> = (0..KEYS)
        .map(|_| {
            (1..=HARMONICS)
                .map(|h| {
                    let magnitude = random.next() / h as f32;
                    let phase = random.next() * TAU;
                    (magnitude * phase.cos(), magnitude * phase.sin())
                })
                .collect()
        })
        .collect();
    additive(|y, h| {
        let pos = y * (KEYS - 1) as f32;
        let i = (pos.floor() as usize).min(KEYS - 2);
        let t = pos - i as f32;
        let at = |k: usize| {
            keys.get(k)
                .and_then(|key| key.get(h - 1))
                .copied()
                .unwrap_or_default()
        };
        let (a, b) = (at(i), at(i + 1));
        (a.0 + (b.0 - a.0) * t, a.1 + (b.1 - a.1) * t)
    })
}

/// Random harmonic weights, from bright to dark.
fn harmonic_morph() -> Table {
    let mut random = Random(0x5EED_0002);
    let weights: Vec<f32> = (0..HARMONICS).map(|_| random.next()).collect();
    additive(|y, h| {
        let w = weights.get(h - 1).copied().unwrap_or(0.0);
        (w / (h as f32).powf(0.5 + 1.5 * y), 0.0)
    })
}
